//! c17: code generated by `build.rs` into `$OUT_DIR/generated.rs` and
//! `include!`d into the `generated` submodule; the generated fn calls
//! `app::gen_target::target_fn`.

pub mod generated {
    include!(concat!(env!("OUT_DIR"), "/generated.rs"));
}

pub fn run() -> u32 {
    generated::generated_entry()
}
